import React, { useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

function UserSubmitCheque({ user }) {
  const [formData, setFormData] = useState({
    account_number: user.account_number,
    amount: '',
    payee: '',
  });
  const [chequeImage, setChequeImage] = useState(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleFileChange = (e) => {
    setChequeImage(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.amount || !formData.payee || !chequeImage) {
      setError('All fields and image are required.');
      return;
    }
    const data = new FormData();
    data.append('account_number', formData.account_number);
    data.append('amount', formData.amount);
    data.append('payee', formData.payee);
    data.append('chequeImage', chequeImage);

    try {
      const response = await axios.post('http://localhost:3001/user/cheques/submit', data);
      if (response.data.success) {
        setSuccess(response.data.message);
        setFormData({ ...formData, amount: '', payee: '' });
        setChequeImage(null);
      } else {
        setError(response.data.message);
      }
    } catch (err) {
      setError('Failed to submit cheque.');
    }
  };

  return (
    <div className="p-8 max-w-md mx-auto">
      <h2 className="text-2xl font-bold mb-4">Submit Cheque</h2>
      <Link to="/user/dashboard">
        <button className="mb-4 bg-gray-500 text-white p-2 rounded hover:bg-gray-600">
          Back to Dashboard
        </button>
      </Link>
      {error && <p className="text-red-500 mb-4">{error}</p>}
      {success && <p className="text-green-500 mb-4">{success}</p>}
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="account_number"
          placeholder="Account Number"
          value={formData.account_number}
          disabled
          className="w-full p-2 mb-2 border rounded bg-gray-100"
        />
        <input
          type="number"
          name="amount"
          placeholder="Amount"
          value={formData.amount}
          onChange={handleInputChange}
          className="w-full p-2 mb-2 border rounded"
        />
        <input
          type="text"
          name="payee"
          placeholder="Payee"
          value={formData.payee}
          onChange={handleInputChange}
          className="w-full p-2 mb-2 border rounded"
        />
        <input
          type="file"
          accept="image/jpeg,image/png"
          onChange={handleFileChange}
          className="w-full p-2 mb-2"
        />
        <button
          type="submit"
          className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600"
        >
          Submit Cheque
        </button>
      </form>
    </div>
  );
}

export default UserSubmitCheque;
